// Validate input before it is used in a URL or a file path.
const { prompt_name, label } = $input.first().json;
if (typeof prompt_name !== 'string' || !/^[a-z0-9][a-z0-9-]{0,99}$/.test(prompt_name)) {
  throw new Error(`get-prompt: invalid prompt_name ${JSON.stringify(prompt_name)}`);
}
const lbl = label || 'production';
if (!/^[a-z0-9][a-z0-9_.-]{0,49}$/i.test(lbl)) {
  throw new Error(`get-prompt: invalid label ${JSON.stringify(label)}`);
}
return [{ json: { prompt_name, label: lbl } }];

const { prompt_name } = $('Validate input').first().json;
const p = $input.first().json;
if (p.type !== 'text' || typeof p.prompt !== 'string' || !p.prompt.trim()) {
  throw new Error(`get-prompt: Langfuse returned an unusable prompt for '${prompt_name}' (type=${p.type})`);
}
return [{ json: {
  prompt_text: p.prompt,
  prompt_name,
  prompt_version: p.version,
  prompt_config: p.config ?? {},
  source: 'langfuse'
} }];

// Langfuse failed (timeout / non-2xx / connection error): serve the last known production text.
const { prompt_name } = $('Validate input').first().json;
const text = $input.first().json.prompt_text;
if (typeof text !== 'string' || !text.trim()) {
  throw new Error(`get-prompt: Langfuse unreachable AND fallback /files/prompts/${prompt_name}.md is empty — run npm run seed-prompts`);
}
return [{ json: { prompt_text: text, prompt_name, prompt_version: null, prompt_config: {}, source: 'file_fallback' } }];
